<div><p class="eyebrow"><?= $e($settings['heading']??'Contact') ?></p><?php if($profile['email']): ?><h2><a href="<?= $e('mailto:'.$profile['email']) ?>"><?= $e($profile['email']) ?></a></h2><?php endif; ?><?php if($profile['phone']): ?><p><?= $e($profile['phone']) ?></p><?php endif; ?><p><?= $e($profile['location']) ?></p><div class="social-links"><?php foreach($profile['social'] as $link): ?><a href="<?= $e($href($link['url'])) ?>" rel="noopener"><?= $e($link['platform']??'Profile') ?></a><?php endforeach; ?></div></div>
